// Drops emails that are not inquiries BEFORE the AI step, so you do not pay for newsletters, auto-replies,
// bounces and your own sent mail. Also prepares a short, clean text for the AI (HTML removed, length capped).
// Input: Gmail Trigger items with "Simplify" off (full message: headers, from, subject, text, html).
const settings = $('Set lead settings').first().json;
const ignore = String(settings.ignoreSenders || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

const header = (msg, name) => {
  const h = msg.headers || {};
  const key = Object.keys(h).find((k) => k.toLowerCase() === name);
  return key ? String(h[key]) : '';
};
const stripHtml = (html) => String(html || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"');

return $input.all().map((item) => {
  const msg = item.json;
  const sender = (msg.from && msg.from.value && msg.from.value[0]) || {};
  const fromEmail = String(sender.address || '').trim().toLowerCase();
  const fromName = String(sender.name || '').trim();
  const subject = String(msg.subject || '').trim();
  // Quoted replies below the first "On … wrote:" are cut: the AI should read only what this person wrote now.
  const body = String(msg.text || stripHtml(msg.html)).split(/\n>|\nOn .{5,120} wrote:/)[0].replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

  let skipReason = '';
  if (!fromEmail) skipReason = 'no sender address';
  else if (ignore.some((word) => fromEmail.includes(word))) skipReason = `ignored sender (${fromEmail})`;
  else if (/^auto-(replied|generated)/i.test(header(msg, 'auto-submitted'))) skipReason = 'auto-reply';
  else if (header(msg, 'list-unsubscribe') || /^(bulk|list|junk)$/i.test(header(msg, 'precedence'))) skipReason = 'newsletter or mailing list';
  else if (/^(re:\s*)?(out of office|automatic reply|auto-?reply|undeliverable|delivery status notification)/i.test(subject)) skipReason = 'auto-reply';
  else if (body.length < 15) skipReason = 'empty message';

  return { json: {
    messageId: msg.id || '',
    fromEmail, fromName, subject,
    receivedAt: msg.date ? new Date(msg.date).toISOString() : new Date().toISOString(),
    body: body.slice(0, Number(settings.maxEmailChars) || 6000),
    skip: skipReason !== '',
    skipReason,
  } };
});

// Checks what the AI returned before anything is saved — the AI can be wrong, so nothing it says is trusted as is:
// the email address always comes from the sender (never from the AI), the budget must be a real number, the phone
// is normalized, text that would become a spreadsheet formula is neutralized, and "not an inquiry" rows are dropped.
// Adds `key` (the sender's email) for the Google Sheets "Append or Update" match: one row per person, updated on repeat.
const settings = $('Set lead settings').first().json;
const emails = $('Is it a real inquiry?').all(); // same order as the AI results

const text = (v, max = 300) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
  return /^[=+\-@]/.test(s) ? "'" + s : s; // "=..." would run as a formula in Google Sheets
};
const money = (v) => {
  if (typeof v === 'number') return Number.isFinite(v) && v > 0 ? Math.round(v) : '';
  const m = String(v ?? '').replace(/[\s,]/g, '').match(/\d+(\.\d+)?/);
  const n = m ? Number(m[0]) * (/\d\s*k\b/i.test(String(v)) ? 1000 : 1) : NaN;
  return Number.isFinite(n) && n > 0 ? Math.round(n) : '';
};
const phone = (v) => { const d = String(v ?? '').replace(/\D/g, ''); return d.length >= 7 && d.length <= 15 ? (String(v).trim().startsWith('+') ? '+' : '') + d : ''; };

return $input.all().map((item, i) => {
  const mail = (emails[i] || {}).json || {};
  const ai = item.json.output || {};
  const isInquiry = ai.is_inquiry === true || String(ai.is_inquiry).toLowerCase() === 'true';
  const budget = money(ai.budget);
  const hot = isInquiry && ((budget !== '' && budget >= Number(settings.hotBudgetMin)) || /\b(asap|urgent|this week|today|tomorrow)\b/i.test(String(ai.deadline || '')));
  const row = {
    key: mail.fromEmail,
    received_at: mail.receivedAt,
    name: text(ai.name || mail.fromName, 120),
    email: mail.fromEmail,
    company: text(ai.company, 120),
    phone: phone(ai.phone),
    service: text(ai.service, 200),
    budget,
    currency: budget === '' ? '' : text(ai.currency || settings.defaultCurrency, 3).toUpperCase(),
    deadline: text(ai.deadline, 60),
    summary: text(ai.summary, 400),
    subject: text(mail.subject, 200),
    priority: hot ? 'hot' : 'normal',
    gmail_link: mail.messageId ? `https://mail.google.com/mail/u/0/#all/${mail.messageId}` : '',
  };
  return { json: { isLead: isInquiry && !!mail.fromEmail, row } };
});

// Formats the Telegram alert for a hot lead in HTML mode. Every value is escaped: an email subject or AI summary
// with "*", "_" or "<" can no longer break the message (Telegram rejects broken formatting).
const settings = $('Set lead settings').first().json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item) => {
  const r = item.json;
  const lines = [`<b>🔥 Hot lead: ${esc(r.name || r.email)}</b>`];
  if (r.company) lines.push(`<b>Company:</b> ${esc(r.company)}`);
  if (r.service) lines.push(`<b>Wants:</b> ${esc(r.service)}`);
  if (r.budget !== '' && r.budget !== undefined) lines.push(`<b>Budget:</b> ${esc(r.budget)} ${esc(r.currency)}`);
  if (r.deadline) lines.push(`<b>When:</b> ${esc(r.deadline)}`);
  if (r.summary) lines.push(esc(r.summary));
  lines.push(`<b>Email:</b> ${esc(r.email)}`);
  if (/^https:\/\/mail\.google\.com\//.test(r.gmail_link || '')) lines.push(`<a href="${esc(r.gmail_link).replace(/"/g, '&quot;')}">Open the email</a>`);
  return { json: { chatId: settings.telegramChatId, text: lines.join('\n').slice(0, 4000) } };
});
